from hbonboard.models import ACTIVE, REJECTED, REVIEW
from hbonboard.util.phone import mask_phone
from hbonboard.util.text import mask_name

TEMPLATES = {
    ACTIVE: "[한빛페이] {name}님, 본인확인이 완료되어 가입이 끝났습니다. 한빛 후불결제도 바로 이용하실 수 있어요.",
    REJECTED: "[한빛페이] {name}님, 입력하신 정보로 본인확인이 되지 않았습니다. 앱에서 다시 시도해 주세요.",
    REVIEW: "[한빛페이] {name}님, 본인확인 결과를 담당자가 확인하고 있습니다.",
}


class Outbox:
    def __init__(self):
        self._messages = []

    def verdict(self, member):
        template = TEMPLATES.get(member.status)
        if template is None:
            return None
        message = {
            "member": member.member_id,
            "to": mask_phone(member.phone),
            "kind": member.status,
            "text": template.format(name=mask_name(member.name)),
        }
        self._messages.append(message)
        return message

    def messages(self, member_id=None):
        if member_id is None:
            return list(self._messages)
        return [m for m in self._messages if m["member"] == member_id]
"""Sign-up form validation and registration."""
from hbonboard.models import Conflict, Member, PENDING
from hbonboard.util.dates import age_on, parse_date
from hbonboard.util.phone import is_mobile, normalize_phone
from hbonboard.util.text import normalize_name


class SignupService:
    def __init__(self, repo, settings, today):
        self.repo = repo
        self.settings = settings
        self.today = today

    def validate(self, payload):
        name = normalize_name(payload.get("name"))
        if not name or len(name) > self.settings.name_max_chars:
            raise ValueError("name is required (max %d characters)" % self.settings.name_max_chars)
        birth = parse_date(payload.get("birth"))
        if birth > self.today:
            raise ValueError("birth date is in the future")
        if age_on(birth.isoformat(), self.today) < self.settings.adult_age:
            raise ValueError("members must be %d or older" % self.settings.adult_age)
        phone = normalize_phone(payload.get("phone"))
        if not is_mobile(phone):
            raise ValueError("phone must be a mobile number")
        channel = str(payload.get("channel", "app")).strip().lower()
        if channel not in self.settings.channels:
            raise ValueError(f"unknown channel {channel}")
        return {"name": name, "birth": birth.isoformat(), "phone": phone, "channel": channel}

    def register(self, payload):
        fields = self.validate(payload)
        if self.repo.by_phone(fields["phone"]) is not None:
            raise Conflict("phone number already registered")
        member = Member(member_id=self.repo.next_id(), **fields)
        member.history.append(PENDING)
        return self.repo.add(member)
"""Identity-check run: sends new members to the vendor and applies verdicts."""
from hbonboard.kyc.requests import build_batch
from hbonboard.kyc.verdicts import apply_verdict
from hbonboard.models import ACTIVE, KYC_NEW, KYC_SENT, REVIEW
from hbonboard.util.dates import age_on


class VerificationService:
    def __init__(self, repo, client, settings, today, notifier=None, on_resolved=None):
        self.repo = repo
        self.client = client
        self.settings = settings
        self.today = today
        self.notifier = notifier
        self.on_resolved = on_resolved

    def _send_new(self):
        fresh = sorted(self.repo.by_kyc_state(KYC_NEW), key=lambda m: m.member_id)
        if not fresh:
            return [], 0
        by_id = {m.member_id: m for m in fresh}
        requests = build_batch(fresh)
        size = self.settings.idchk_batch_lines
        jobs = []
        for start in range(0, len(requests), size):
            chunk = requests[start:start + size]
            ticket = self.client.submit(chunk)
            jobs.append(ticket.job_id)
            for request in chunk:
                member = by_id[request.ref]
                member.kyc_state = KYC_SENT
                member.kyc_job = ticket.job_id
                member.history.append(KYC_SENT)
        return jobs, len(fresh)

    def _collect(self):
        resolved, waiting = [], []
        for member in sorted(self.repo.by_kyc_state(KYC_SENT), key=lambda m: m.member_id):
            code = self.client.result(member.member_id)
            if code is None:
                # the vendor has not answered for this one yet; ask again next run
                waiting.append(member.member_id)
                continue
            apply_verdict(member, code)
            self._age_gate(member)
            if self.notifier:
                self.notifier.verdict(member)
            resolved.append({"id": member.member_id, "status": member.status})
        return resolved, waiting

    def _age_gate(self, member):
        # second age check right before a member becomes active
        # (inspection follow-up 2025-05, item 4)
        # TODO: sign-up already refuses anyone under adult_age -- is this still needed?
        if member.status == ACTIVE and age_on(member.birth, self.today) < self.settings.adult_age:
            member.status = REVIEW
            member.history[-1] = REVIEW

    def run(self):
        jobs, sent = self._send_new()
        resolved, waiting = self._collect()
        if resolved and self.on_resolved:
            self.on_resolved()
        return {"jobs": jobs, "sent": sent, "resolved": resolved, "waiting": len(waiting)}
"""Thin wrapper around the identity-verification vendor CLI (vendor/bin/idchk)."""
import os
import subprocess
import tempfile

from hbonboard.models import JobTicket, VendorError

# the vendor answers this for a reference it has no verdict for (yet)
NO_RESULT = "E31"


class IdchkClient:
    def __init__(self, settings):
        self.binary = settings.idchk_bin
        self.home = settings.idchk_home or os.environ.get("IDCHK_HOME", "")
        self.timeout = settings.idchk_timeout

    def _run(self, *args):
        env = dict(os.environ)
        if self.home:
            env["IDCHK_HOME"] = self.home
        proc = subprocess.run(
            [self.binary, *args],
            capture_output=True,
            text=True,
            encoding="utf-8",
            env=env,
            timeout=self.timeout,
        )
        if proc.returncode != 0:
            code = (proc.stderr.strip().splitlines() or ["E??"])[-1]
            raise VendorError(code, args[0])
        return proc.stdout

    def submit(self, requests):
        """Send one batch file; returns the vendor job ticket."""
        lines = [f"{r.ref}\t{r.name}\t{r.birth}\t{r.phone}" for r in requests]
        fd, path = tempfile.mkstemp(prefix="idchk-", suffix=".tsv")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                f.write("\n".join(lines) + "\n")
            out = self._run("batch", "--in", path)
        finally:
            os.unlink(path)
        job_id, _, count = out.strip().partition("\t")
        if not job_id.startswith("J") or not count.isdigit():
            raise VendorError("E??", "batch")
        if int(count) != len(lines):
            # the vendor read a different number of lines than we wrote
            raise VendorError("E??", "batch")
        return JobTicket(job_id, int(count))

    def result(self, ref):
        """Verdict code for a reference, or None while the vendor has none."""
        try:
            out = self._run("result", ref)
        except VendorError as exc:
            if exc.code == NO_RESULT:
                return None
            raise
        fields = dict(line.split(" ", 1) for line in out.splitlines() if " " in line)
        return int(fields["v"])

    def job(self, job_id):
        out = self._run("job", job_id)
        return dict(line.split(" ", 1) for line in out.splitlines() if " " in line)
"""Turns members waiting for an identity check into vendor request lines."""
from hbonboard.models import KycRequest
from hbonboard.util.dates import compact
from hbonboard.util.text import vendor_name


def to_request(member):
    return KycRequest(
        ref=member.member_id,
        name=vendor_name(member.name),
        birth=compact(member.birth),
        phone=member.phone,
    )


def build_batch(members):
    """One line per member, in phone-number order (the vendor's matching key)."""
    seen, requests = set(), []
    for member in members:
        if member.member_id in seen:
            continue
        seen.add(member.member_id)
        requests.append(to_request(member))
    return sorted(requests, key=lambda r: r.phone)
"""Vendor verdict codes -> member status."""
from hbonboard.models import ACTIVE, KYC_DONE, REJECTED, REVIEW

# 1 = identity matched, 2 = identity did not match; anything else goes to a person
VERDICT_STATUS = {1: ACTIVE, 2: REJECTED}


def status_for(code):
    return VERDICT_STATUS.get(code, REVIEW)


def apply_verdict(member, code):
    member.verdict = code
    member.status = status_for(code)
    member.kyc_state = KYC_DONE
    member.history.append(member.status)
    return member
"""Date helpers (ISO strings only; no time zones involved)."""
import datetime as _dt


def parse_date(value):
    raw = str(value or "").strip()
    if len(raw) == 8 and raw.isdigit():
        raw = f"{raw[:4]}-{raw[4:6]}-{raw[6:]}"
    try:
        return _dt.date.fromisoformat(raw)
    except ValueError:
        raise ValueError(f"invalid date: {value!r}") from None


def compact(iso_date):
    """2001-02-03 -> 20010203"""
    return parse_date(iso_date).strftime("%Y%m%d")


def age_on(birth, today):
    """Full years (만 나이) on `today`."""
    b = parse_date(birth)
    years = today.year - b.year
    if (today.month, today.day) < (b.month, b.day):
        years -= 1
    return years
