    def submit(self, requests):
        """Send one batch file; returns the vendor job ticket."""
        lines = [f"{r.ref}\t{r.name}\t{r.birth}\t{r.phone}" for r in requests]
        fd, path = tempfile.mkstemp(prefix="idchk-", suffix=".tsv")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                f.write("\n".join(lines) + "\n")
            out = self._run("batch", "--in", path)
        finally:
            os.unlink(path)
        job_id, _, count = out.strip().partition("\t")
        if not job_id.startswith("J") or not count.isdigit():
            raise VendorError("E??", "batch")
        if int(count) != len(lines):
            # the vendor read a different number of lines than we wrote
            raise VendorError("E??", "batch")
        return JobTicket(job_id, int(count))

    def result(self, ref):
        """Verdict code for a reference, or None while the vendor has none."""
        try:
            out = self._run("result", ref)
        except VendorError as exc:
            if exc.code == NO_RESULT:
                return None
            raise
        fields = dict(line.split(" ", 1) for line in out.splitlines() if " " in line)
        return int(fields["v"])

    def job(self, job_id):
        out = self._run("job", job_id)
        return dict(line.split(" ", 1) for line in out.splitlines() if " " in line)
"""Turns members waiting for an identity check into vendor request lines."""
from hbonboard.models import KycRequest
from hbonboard.util.dates import compact
from hbonboard.util.text import vendor_name


def to_request(member):
    return KycRequest(
        ref=member.member_id,
        name=vendor_name(member.name),
        birth=compact(member.birth),
        phone=member.phone,
    )


def build_batch(members):
    """One line per member, in phone-number order (the vendor's matching key)."""
    seen, requests = set(), []
    for member in members:
        if member.member_id in seen:
            continue
        seen.add(member.member_id)
        requests.append(to_request(member))
    return sorted(requests, key=lambda r: r.phone)
"""Vendor verdict codes -> member status."""
from hbonboard.models import ACTIVE, KYC_DONE, REJECTED, REVIEW

# 1 = identity matched, 2 = identity did not match; anything else goes to a person
VERDICT_STATUS = {1: ACTIVE, 2: REJECTED}


def status_for(code):
    return VERDICT_STATUS.get(code, REVIEW)


def apply_verdict(member, code):
    member.verdict = code
    member.status = status_for(code)
    member.kyc_state = KYC_DONE
    member.history.append(member.status)
    return member
"""Date helpers (ISO strings only; no time zones involved)."""
import datetime as _dt


def parse_date(value):
    raw = str(value or "").strip()
    if len(raw) == 8 and raw.isdigit():
        raw = f"{raw[:4]}-{raw[4:6]}-{raw[6:]}"
    try:
        return _dt.date.fromisoformat(raw)
    except ValueError:
        raise ValueError(f"invalid date: {value!r}") from None


def compact(iso_date):
    """2001-02-03 -> 20010203"""
    return parse_date(iso_date).strftime("%Y%m%d")


def age_on(birth, today):
    """Full years (만 나이) on `today`."""
    b = parse_date(birth)
    years = today.year - b.year
    if (today.month, today.day) < (b.month, b.day):
        years -= 1
    return years
